    /// Enqueue the persistent rank-0 direct all-reduce prototype. The dispatch
    /// stays resident until `total_ops` host-triggered operations complete.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_allreduce_direct_persistent(
        &mut self,
        own_va: u64,
        ptrs_va: u64,
        ctrl_va: u64,
        gbar_va: u64,
        parts: u32,
        n: u32,
        total_ops: u32,
        num_wg: u32,
    ) -> Result<()> {
        if aql_serialize_enabled() {
            return Err(anyhow::anyhow!(
                "persistent direct all-reduce cannot run with MAINARCH_AQL_SERIALIZE enabled"
            ));
        }
        let k = self.code.kernel("allreduce_direct_persistent")?;
        let work = num_wg.max(1) * DEFAULT_WG;
        self.arm_1d(&k, work, |b, grid, wg| {
            b.put_u64(0, own_va);
            b.put_u64(8, ptrs_va);
            b.put_u64(16, ctrl_va);
            b.put_u64(24, gbar_va);
            b.put_u32(32, parts);
            b.put_u32(36, n);
            b.put_u32(40, total_ops);
            // Explicit args are 44 bytes; hidden args are 8-byte aligned.
            b.put_hidden_1d(48, grid, wg);
        })
    }

