    /// Enqueue (without waiting) the Qwen3-4B rank-local capstone split:
    /// exactly 4 query heads share one FP4 KV head, removing the 8-head padding
    /// required by the wider grouped kernel.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_attn_decode_split_fp4_gqa4_paged_groups(
        &mut self,
        q_va: u64,
        k_va: u64,
        v_va: u64,
        scale_k_va: u64,
        scale_v_va: u64,
        block_table_va: u64,
        block_size: u32,
        physical_blocks: u32,
        partials_va: u64,
        n: u32,
        d: u32,
        scale: f32,
        num_splits: u32,
        num_groups: u32,
        q_heads_per_kv: u32,
        rows_per_head: u32,
    ) -> Result<()> {
        let kern = self
            .code
            .kernel("attn_decode_split2_fp4_gqa4_paged_groups")?;
        if n == 0 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups N must be non-zero"
            ));
        }
        if d != 128 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups requires D=128 (got {d})"
            ));
        }
        if num_splits == 0 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups num_splits must be non-zero"
            ));
        }
        if num_groups == 0 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups num_groups must be non-zero"
            ));
        }
        if q_heads_per_kv != 4 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups requires q_heads_per_kv=4 (got {q_heads_per_kv})"
            ));
        }
        if block_size == 0 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups block_size must be non-zero"
            ));
        }
        if physical_blocks == 0 {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups physical_blocks must be non-zero"
            ));
        }
        let min_rows = physical_blocks.checked_mul(block_size).ok_or_else(|| {
            anyhow!("attn_decode_split2_fp4_gqa4_paged_groups rows_per_head overflow")
        })?;
        if rows_per_head < min_rows {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups rows_per_head ({rows_per_head}) is smaller than physical_blocks*block_size ({min_rows})"
            ));
        }
        let blocks = n.div_ceil(block_size);
        if blocks > physical_blocks {
            return Err(anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups logical blocks ({blocks}) exceed physical block capacity ({physical_blocks})"
            ));
        }
        const GQA_GROUP: u64 = 4;
        let heads = u64::from(num_groups) * GQA_GROUP;
        let max_head_base = u64::from(num_groups - 1) * GQA_GROUP;
        let kv_heads = max_head_base / u64::from(q_heads_per_kv) + 1;
        let num_wg = num_groups.checked_mul(num_splits).ok_or_else(|| {
            anyhow!(
                "attn_decode_split2_fp4_gqa4_paged_groups workgroup count overflows: groups={num_groups} splits={num_splits}"
            )
        })?;
        self.validate_kernel_spans(
            "attn_decode_split2_fp4_gqa4_paged_groups",
            &[
                (
                    "q",
                    q_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "q",
                        &[heads, d as u64],
                        2,
                    )?,
                ),
                (
                    "K",
                    k_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "K",
                        &[kv_heads, rows_per_head as u64, 64],
                        1,
                    )?,
                ),
                (
                    "V",
                    v_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "V",
                        &[kv_heads, rows_per_head as u64, 64],
                        1,
                    )?,
                ),
                (
                    "scale_k",
                    scale_k_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "scale_k",
                        &[kv_heads, rows_per_head as u64, 4],
                        1,
                    )?,
                ),
                (
                    "scale_v",
                    scale_v_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "scale_v",
                        &[kv_heads, rows_per_head as u64, 4],
                        1,
                    )?,
                ),
                (
                    "block_table",
                    block_table_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "block_table",
                        &[blocks as u64],
                        4,
                    )?,
                ),
                (
                    "partials",
                    partials_va,
                    bytes_for(
                        "attn_decode_split2_fp4_gqa4_paged_groups",
                        "partials",
                        &[heads, num_splits as u64, (d + 2) as u64],
                        4,
                    )?,
                ),
            ],
        )?;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, q_va);
            b.put_u64(8, k_va);
            b.put_u64(16, v_va);
            b.put_u64(24, scale_k_va);
            b.put_u64(32, scale_v_va);
            b.put_u64(40, block_table_va);
            b.put_u32(48, block_size);
            b.put_u32(52, physical_blocks);
            b.put_u64(56, partials_va);
            b.put_u32(64, n);
            b.put_u32(68, d);
            b.put_f32(72, scale);
            b.put_u32(76, num_splits);
            b.put_u32(80, num_groups);
            b.put_u32(84, q_heads_per_kv);
            b.put_u32(88, rows_per_head);
        })
    }

