    /// Convert a global TP vocab token into a shard-local token on-device.
    /// `owner_flags[0]` is 1 when the token belongs to this shard, otherwise 0.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_qwen_global_token_to_local_token(
        &mut self,
        global_tokens_va: u64,
        local_tokens_va: u64,
        owner_flags_va: u64,
        global_index: u32,
        local_index: u32,
        token_count: u32,
        global_vocab_start: u32,
        local_vocab_rows: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("qwen_global_token_to_local_token")?;
        if token_count == 0 {
            return Err(anyhow!(
                "qwen_global_token_to_local_token token_count must be non-zero"
            ));
        }
        if local_vocab_rows == 0 {
            return Err(anyhow!(
                "qwen_global_token_to_local_token local_vocab_rows must be non-zero"
            ));
        }
        self.validate_kernel_spans(
            "qwen_global_token_to_local_token",
            &[
                (
                    "global_tokens",
                    global_tokens_va,
                    bytes_for(
                        "qwen_global_token_to_local_token",
                        "global_tokens",
                        &[token_count as u64],
                        4,
                    )?,
                ),
                (
                    "local_tokens",
                    local_tokens_va,
                    bytes_for(
                        "qwen_global_token_to_local_token",
                        "local_tokens",
                        &[token_count as u64],
                        4,
                    )?,
                ),
                ("owner_flags", owner_flags_va, 4),
            ],
        )?;
        self.arm_grid(&kern, 1, 1, |b| {
            b.put_u64(0, global_tokens_va);
            b.put_u64(8, local_tokens_va);
            b.put_u64(16, owner_flags_va);
            b.put_u32(24, global_index);
            b.put_u32(28, local_index);
            b.put_u32(32, token_count);
            b.put_u32(36, global_vocab_start);
            b.put_u32(40, local_vocab_rows);
        })
    }

    /// Enqueue greedy argmax into `tokens[step[0] + 1]`, then increment
    /// `step[0]`. This keeps the token-index metadata at a fixed device
    /// address for future graph replay.
    pub fn arm_argmax_f32_step(
        &mut self,
        logits_va: u64,
        tokens_va: u64,
        step_va: u64,
        token_count: u32,
        n: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("argmax_f32_step")?;
        if n == 0 {
            return Err(anyhow!("argmax_f32_step N must be non-zero"));
        }
        if token_count < 2 {
            return Err(anyhow!("argmax_f32_step token_count must be at least 2"));
        }
        self.validate_kernel_spans(
            "argmax_f32_step",
            &[
                (
                    "logits",
                    logits_va,
                    bytes_for(
                        "argmax_f32_step",
                        "logits",
                        &[(token_count - 1) as u64, n as u64],
                        4,
                    )?,
                ),
                (
                    "tokens",
                    tokens_va,
                    bytes_for("argmax_f32_step", "tokens", &[token_count as u64], 4)?,
                ),
                ("step", step_va, 4),
            ],
        )?;
        self.arm_grid(&kern, 1, 256, |b| {
            b.put_u64(0, logits_va);
            b.put_u64(8, tokens_va);
            b.put_u64(16, step_va);
            b.put_u32(24, token_count);
            b.put_u32(28, n);
        })
    }

    /// Enqueue fused decode Q/K/V GEMV. All three matrices share the same input
    /// vector and K dimension; outputs remain separate f32 buffers.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_gemv_qkv(
        &mut self,
        wq_va: u64,
        wk_va: u64,
        wv_va: u64,
        x_va: u64,
        yq_va: u64,
        yk_va: u64,
        yv_va: u64,
        nq: u32,
        nkv: u32,
        k: u32,
    ) -> Result<()> {
        let total = nq
            .checked_add(
                nkv.checked_mul(2)
                    .ok_or_else(|| anyhow!("gemv_qkv_f16 NKV overflows: NKV={nkv}"))?,
            )
            .ok_or_else(|| anyhow!("gemv_qkv_f16 total row count overflows: NQ={nq}, NKV={nkv}"))?;
        if k == 4096 {
            let kern = self.code.kernel("gemv_qkv_f16_k4096")?;
            self.validate_kernel_spans(
                "gemv_qkv_f16_k4096",
                &[
                    ("Wq", wq_va, (nq as u64) * 4096 * 2),
                    ("Wk", wk_va, (nkv as u64) * 4096 * 2),
                    ("Wv", wv_va, (nkv as u64) * 4096 * 2),
                    ("x", x_va, 4096 * 2),
                    ("yq", yq_va, (nq as u64) * 4),
                    ("yk", yk_va, (nkv as u64) * 4),
                    ("yv", yv_va, (nkv as u64) * 4),
                ],
            )?;
            let num_wg = total.div_ceil(4);
            return self.arm_grid(&kern, num_wg, 256, |b| {
                b.put_u64(0, wq_va);
                b.put_u64(8, wk_va);
                b.put_u64(16, wv_va);
                b.put_u64(24, x_va);
                b.put_u64(32, yq_va);
                b.put_u64(40, yk_va);
                b.put_u64(48, yv_va);
                b.put_u32(56, nq);
                b.put_u32(60, nkv);
            });
        }
        let kern = self.code.kernel("gemv_qkv_f16")?;
        self.validate_kernel_spans(
            "gemv_qkv_f16",
            &[
                (
                    "Wq",
                    wq_va,
                    bytes_for("gemv_qkv_f16", "Wq", &[nq as u64, k as u64], 2)?,
                ),
                (
                    "Wk",
                    wk_va,
                    bytes_for("gemv_qkv_f16", "Wk", &[nkv as u64, k as u64], 2)?,
                ),
                (
                    "Wv",
                    wv_va,
                    bytes_for("gemv_qkv_f16", "Wv", &[nkv as u64, k as u64], 2)?,
                ),
                ("x", x_va, bytes_for("gemv_qkv_f16", "x", &[k as u64], 2)?),
                (
                    "yq",
                    yq_va,
                    bytes_for("gemv_qkv_f16", "yq", &[nq as u64], 4)?,
                ),
                (
                    "yk",
                    yk_va,
                    bytes_for("gemv_qkv_f16", "yk", &[nkv as u64], 4)?,
                ),
                (
                    "yv",
                    yv_va,
                    bytes_for("gemv_qkv_f16", "yv", &[nkv as u64], 4)?,
                ),
            ],
        )?;
        let num_wg = total.div_ceil(4);
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, wq_va);
            b.put_u64(8, wk_va);
            b.put_u64(16, wv_va);
            b.put_u64(24, x_va);
            b.put_u64(32, yq_va);
            b.put_u64(40, yk_va);
            b.put_u64(48, yv_va);
            b.put_u32(56, nq);
            b.put_u32(60, nkv);
            b.put_u32(64, k);
        })
    }

    /// Enqueue (without waiting) FP8-weight decode GEMV: y = scale_w ⊙ (W_fp8 · x).
    pub fn arm_gemv_fp8(
        &mut self,
        w_va: u64,
        scale_w_va: u64,
        x_va: u64,
        y_va: u64,
        n: u32,
        k: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("gemv_fp8")?;
        self.validate_kernel_spans(
            "gemv_fp8",
            &[
                (
                    "W",
                    w_va,
                    bytes_for("gemv_fp8", "W", &[n as u64, k as u64], 1)?,
                ),
                (
                    "scale_w",
                    scale_w_va,
                    bytes_for("gemv_fp8", "scale_w", &[n as u64], 4)?,
                ),
                ("x", x_va, bytes_for("gemv_fp8", "x", &[k as u64], 2)?),
                ("y", y_va, bytes_for("gemv_fp8", "y", &[n as u64], 4)?),
            ],
        )?;
        let num_wg = n.div_ceil(4);
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, w_va);
            b.put_u64(8, scale_w_va);
            b.put_u64(16, x_va);
            b.put_u64(24, y_va);
            b.put_u32(32, n);
            b.put_u32(36, k);
        })
    }

    /// Enqueue FP8-weight decode GEMV with 128x128 E8M0 block scales packed as
    /// four scale bytes per u32 along the K-block dimension.
    pub fn arm_gemv_fp8_wblock_e8m0(
        &mut self,
        w_va: u64,
        scale_w_va: u64,
        x_va: u64,
        y_va: u64,
        n: u32,
        k: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("gemv_fp8_wblock_e8m0")?;
        let nblocks = n.div_ceil(128);
        let kblocks = k.div_ceil(128);
        let packed_kblocks = kblocks.div_ceil(4);
        self.validate_kernel_spans(
            "gemv_fp8_wblock_e8m0",
            &[
                ("W", w_va, n as u64 * k as u64),
                (
                    "scale_w",
                    scale_w_va,
                    nblocks as u64 * packed_kblocks as u64 * 4,
                ),
                ("x", x_va, k as u64 * 2),
                ("y", y_va, n as u64 * 4),
            ],
        )?;
        let num_wg = n.div_ceil(4);
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, w_va);
            b.put_u64(8, scale_w_va);
            b.put_u64(16, x_va);
            b.put_u64(24, y_va);
            b.put_u32(32, n);
            b.put_u32(36, k);
            b.put_u32(40, kblocks);
            b.put_u32(44, packed_kblocks);
        })
    }

