    /// Enqueue the minimal CDNA4 scaled-MFMA execution probe. A/B are eight
    /// dwords each, scales are two dwords, and O is four f32 values written by
    /// lane 0. This validates V_MFMA_SCALE_F32_16X16X128_F8F6F4 retirement.
    pub fn arm_mfma_scale_f8f6f4_probe(
        &mut self,
        a_va: u64,
        b_va: u64,
        scale_va: u64,
        out_va: u64,
    ) -> Result<()> {
        let kern = self.code.kernel("mfma_scale_f8f6f4_probe")?;
        self.validate_kernel_spans(
            "mfma_scale_f8f6f4_probe",
            &[
                ("A", a_va, 8 * 4),
                ("B", b_va, 8 * 4),
                ("S", scale_va, 2 * 4),
                ("O", out_va, 4 * 4),
            ],
        )?;
        self.arm_grid(&kern, 1, 64, |b| {
            b.put_u64(0, a_va);
            b.put_u64(8, b_va);
            b.put_u64(16, scale_va);
            b.put_u64(24, out_va);
        })
    }

    /// Numeric readiness gate for CDNA4 scaled-MFMA. Runs zero FP8 operands
    /// through known immediate forms and expects the accumulator to survive.
    pub fn arm_mfma_scale_f8f6f4_calibrate(
        &mut self,
        a_va: u64,
        b_va: u64,
        scale_va: u64,
        out_va: u64,
    ) -> Result<()> {
        let kern = self.code.kernel("mfma_scale_f8f6f4_calibrate")?;
        self.validate_kernel_spans(
            "mfma_scale_f8f6f4_calibrate",
            &[
                ("A", a_va, 8 * 4),
                ("B", b_va, 8 * 4),
                ("S", scale_va, 2 * 4),
                ("O", out_va, 16 * 4),
            ],
        )?;
        self.arm_grid(&kern, 1, 64, |b| {
            b.put_u64(0, a_va);
            b.put_u64(8, b_va);
            b.put_u64(16, scale_va);
            b.put_u64(24, out_va);
        })
    }

    /// 128x128 block-scaled FP8 GEMV consuming tile-major/preshuffled weights.
    /// Each tile is 16 bytes of metadata (four 32-column E8M0 scale slots plus
    /// reserved bytes) followed by a 128x128 FP8 tile body.
    pub fn arm_gemv_fp8_wblock_tiled_e8m0(
        &mut self,
        w_tiled_va: u64,
        x_va: u64,
        y_va: u64,
        n: u32,
        k: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("gemv_fp8_wblock_tiled_e8m0")?;
        let nblocks = n.div_ceil(128);
        let kblocks = k.div_ceil(128);
        let tile_stride = 16u32 + 128 * 128;
        self.validate_kernel_spans(
            "gemv_fp8_wblock_tiled_e8m0",
            &[
                (
                    "WT",
                    w_tiled_va,
                    nblocks as u64 * kblocks as u64 * tile_stride as u64,
                ),
                ("x", x_va, k as u64 * 2),
                ("y", y_va, n as u64 * 4),
            ],
        )?;
        let num_wg = n.div_ceil(4);
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, w_tiled_va);
            b.put_u64(8, x_va);
            b.put_u64(16, y_va);
            b.put_u32(24, n);
            b.put_u32(28, k);
            b.put_u32(32, kblocks);
            b.put_u32(36, tile_stride);
        })
    }

    /// Same 128x128 block-scaled FP8 GEMV with f32 scales. This is the baseline
    /// for packed-scale consumption overhead.
    pub fn arm_gemv_fp8_wblock_f32(
        &mut self,
        w_va: u64,
        scale_w_va: u64,
        x_va: u64,
        y_va: u64,
        n: u32,
        k: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("gemv_fp8_wblock_f32")?;
        let nblocks = n.div_ceil(128);
        let kblocks = k.div_ceil(128);
        self.validate_kernel_spans(
            "gemv_fp8_wblock_f32",
            &[
                ("W", w_va, n as u64 * k as u64),
                ("scale_w", scale_w_va, nblocks as u64 * kblocks as u64 * 4),
                ("x", x_va, k as u64 * 2),
                ("y", y_va, n as u64 * 4),
            ],
        )?;
        let num_wg = n.div_ceil(4);
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, w_va);
            b.put_u64(8, scale_w_va);
            b.put_u64(16, x_va);
            b.put_u64(24, y_va);
            b.put_u32(32, n);
            b.put_u32(36, k);
            b.put_u32(40, kblocks);
        })
    }

    /// Enqueue (without waiting) zeroing of an f32 buffer of n elements.
    pub fn arm_zero_f32(&mut self, va: u64, n: u32) -> Result<()> {
        let kern = self.code.kernel("zero_f32")?;
        self.validate_kernel_spans(
            "zero_f32",
            &[("b", va, bytes_for("zero_f32", "b", &[n as u64], 4)?)],
        )?;
        let num_wg = 256u32;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, va);
            b.put_u32(8, n);
            b.put_u32(12, num_wg * 256);
        })
    }

    /// Enqueue (without waiting) on-device KV append: write k,v ([nkv*D]) into the
    /// [nkv][Lmax][D] caches at logical position `pos`.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_kv_append(
        &mut self,
        kcache_va: u64,
        vcache_va: u64,
        k_va: u64,
        v_va: u64,
        nkv: u32,
        lmax: u32,
        pos: u32,
        d: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("kv_append")?;
        if pos >= lmax {
            return Err(anyhow!(
                "mainarch GPU VA guard: kernel kv_append pos {pos} out of range for Lmax {lmax}"
            ));
        }
        self.validate_kernel_spans(
            "kv_append",
            &[
                (
                    "kcache",
                    kcache_va,
                    bytes_for(
                        "kv_append",
                        "kcache",
                        &[nkv as u64, lmax as u64, d as u64],
                        2,
                    )?,
                ),
                (
                    "vcache",
                    vcache_va,
                    bytes_for(
                        "kv_append",
                        "vcache",
                        &[nkv as u64, lmax as u64, d as u64],
                        2,
                    )?,
                ),
                (
                    "k",
                    k_va,
                    bytes_for("kv_append", "k", &[nkv as u64, d as u64], 2)?,
                ),
                (
                    "v",
                    v_va,
                    bytes_for("kv_append", "v", &[nkv as u64, d as u64], 2)?,
                ),
            ],
        )?;
        let num_wg = 64u32;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, kcache_va);
            b.put_u64(8, vcache_va);
            b.put_u64(16, k_va);
            b.put_u64(24, v_va);
            b.put_u32(32, nkv);
            b.put_u32(36, lmax);
            b.put_u32(40, pos);
            b.put_u32(44, d);
            b.put_u32(48, num_wg * 256);
        })
    }

    /// Enqueue FlashInfer-style paged KV append. k/v are
    /// [append_count][nkv][D]. Caches are NHD pages:
    /// [physical_blocks][block_size][nkv][D].
    #[allow(clippy::too_many_arguments)]
    pub fn arm_kv_append_paged(
        &mut self,
        kcache_va: u64,
        vcache_va: u64,
        k_va: u64,
        v_va: u64,
        indices_va: u64,
        indptr_va: u64,
        last_page_len_va: u64,
        batch_indices_va: u64,
        positions_va: u64,
        append_count: u32,
        batch_size: u32,
        total_indices: u32,
        physical_blocks: u32,
        nkv: u32,
        block_size: u32,
        d: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("kv_append_paged")?;
        if append_count == 0 {
            return Err(anyhow!("kv_append_paged append_count must be non-zero"));
        }
        if batch_size == 0 {
            return Err(anyhow!("kv_append_paged batch_size must be non-zero"));
        }
        if total_indices == 0 {
            return Err(anyhow!("kv_append_paged total_indices must be non-zero"));
        }
        if physical_blocks == 0 {
            return Err(anyhow!("kv_append_paged physical_blocks must be non-zero"));
        }
        if nkv == 0 || block_size == 0 || d == 0 {
            return Err(anyhow!(
                "kv_append_paged requires non-zero nkv/block_size/D"
            ));
        }
        self.validate_kernel_spans(
            "kv_append_paged",
            &[
                (
                    "kcache",
                    kcache_va,
                    bytes_for(
                        "kv_append_paged",
                        "kcache",
                        &[
                            physical_blocks as u64,
                            block_size as u64,
                            nkv as u64,
                            d as u64,
                        ],
                        2,
                    )?,
                ),
                (
                    "vcache",
                    vcache_va,
                    bytes_for(
                        "kv_append_paged",
                        "vcache",
                        &[
                            physical_blocks as u64,
                            block_size as u64,
                            nkv as u64,
                            d as u64,
                        ],
                        2,
                    )?,
                ),
                (
                    "k",
                    k_va,
                    bytes_for(
                        "kv_append_paged",
                        "k",
                        &[append_count as u64, nkv as u64, d as u64],
                        2,
                    )?,
                ),
                (
                    "v",
                    v_va,
                    bytes_for(
                        "kv_append_paged",
                        "v",
                        &[append_count as u64, nkv as u64, d as u64],
                        2,
                    )?,
                ),
                (
                    "indices",
                    indices_va,
                    bytes_for("kv_append_paged", "indices", &[total_indices as u64], 4)?,
                ),
                (
                    "indptr",
                    indptr_va,
                    bytes_for("kv_append_paged", "indptr", &[batch_size as u64 + 1], 4)?,
                ),
                (
                    "last_page_len",
                    last_page_len_va,
                    bytes_for("kv_append_paged", "last_page_len", &[batch_size as u64], 4)?,
                ),
                (
                    "batch_indices",
                    batch_indices_va,
                    bytes_for(
                        "kv_append_paged",
                        "batch_indices",
                        &[append_count as u64],
                        4,
                    )?,
                ),
                (
                    "positions",
                    positions_va,
                    bytes_for("kv_append_paged", "positions", &[append_count as u64], 4)?,
                ),
            ],
        )?;
        let num_wg = 64u32;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, kcache_va);
            b.put_u64(8, vcache_va);
            b.put_u64(16, k_va);
            b.put_u64(24, v_va);
            b.put_u64(32, indices_va);
            b.put_u64(40, indptr_va);
            b.put_u64(48, last_page_len_va);
            b.put_u64(56, batch_indices_va);
            b.put_u64(64, positions_va);
            b.put_u32(72, append_count);
            b.put_u32(76, batch_size);
            b.put_u32(80, total_indices);
            b.put_u32(84, physical_blocks);
            b.put_u32(88, nkv);
            b.put_u32(92, block_size);
            b.put_u32(96, d);
            b.put_u32(100, num_wg * 256);
        })
    }

    /// Enqueue FlashInfer-style append of already-quantized FP4 KV rows into
    /// physical pages consumed by attn_decode_split2_fp4_gqa_paged.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_kv_append_paged_fp4(
        &mut self,
        kcache_va: u64,
        vcache_va: u64,
        scale_k_va: u64,
        scale_v_va: u64,
        k_va: u64,
        v_va: u64,
        src_scale_k_va: u64,
        src_scale_v_va: u64,
        indices_va: u64,
        indptr_va: u64,
        last_page_len_va: u64,
        batch_indices_va: u64,
        positions_va: u64,
        append_count: u32,
        batch_size: u32,
        total_indices: u32,
        physical_blocks: u32,
        block_size: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("kv_append_paged_fp4")?;
        if append_count == 0 {
            return Err(anyhow!("kv_append_paged_fp4 append_count must be non-zero"));
        }
        if batch_size == 0 {
            return Err(anyhow!("kv_append_paged_fp4 batch_size must be non-zero"));
        }
        if total_indices == 0 {
            return Err(anyhow!(
                "kv_append_paged_fp4 total_indices must be non-zero"
            ));
        }
        if physical_blocks == 0 {
            return Err(anyhow!(
                "kv_append_paged_fp4 physical_blocks must be non-zero"
            ));
        }
        if block_size == 0 {
            return Err(anyhow!("kv_append_paged_fp4 block_size must be non-zero"));
        }
        append_count.checked_mul(136).ok_or_else(|| {
            anyhow!(
                "kv_append_paged_fp4 launch item count overflows u32: append_count={append_count}, per_token=136"
            )
        })?;
        physical_blocks.checked_mul(block_size).ok_or_else(|| {
            anyhow!(
                "kv_append_paged_fp4 physical row count overflows u32: physical_blocks={physical_blocks}, block_size={block_size}"
            )
        })?;
        self.validate_kernel_spans(
            "kv_append_paged_fp4",
            &[
                (
                    "kcache",
                    kcache_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "kcache",
                        &[physical_blocks as u64, block_size as u64, 64],
                        1,
                    )?,
                ),
                (
                    "vcache",
                    vcache_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "vcache",
                        &[physical_blocks as u64, block_size as u64, 64],
                        1,
                    )?,
                ),
                (
                    "scale_k",
                    scale_k_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "scale_k",
                        &[physical_blocks as u64, block_size as u64, 4],
                        1,
                    )?,
                ),
                (
                    "scale_v",
                    scale_v_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "scale_v",
                        &[physical_blocks as u64, block_size as u64, 4],
                        1,
                    )?,
                ),
                (
                    "k",
                    k_va,
                    bytes_for("kv_append_paged_fp4", "k", &[append_count as u64, 64], 1)?,
                ),
                (
                    "v",
                    v_va,
                    bytes_for("kv_append_paged_fp4", "v", &[append_count as u64, 64], 1)?,
                ),
                (
                    "src_scale_k",
                    src_scale_k_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "src_scale_k",
                        &[append_count as u64, 4],
                        1,
                    )?,
                ),
                (
                    "src_scale_v",
                    src_scale_v_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "src_scale_v",
                        &[append_count as u64, 4],
                        1,
                    )?,
                ),
                (
                    "indices",
                    indices_va,
                    bytes_for("kv_append_paged_fp4", "indices", &[total_indices as u64], 4)?,
                ),
                (
                    "indptr",
                    indptr_va,
                    bytes_for("kv_append_paged_fp4", "indptr", &[batch_size as u64 + 1], 4)?,
                ),
                (
                    "last_page_len",
                    last_page_len_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "last_page_len",
                        &[batch_size as u64],
                        4,
                    )?,
                ),
                (
                    "batch_indices",
                    batch_indices_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "batch_indices",
                        &[append_count as u64],
                        4,
                    )?,
                ),
                (
                    "positions",
                    positions_va,
                    bytes_for(
                        "kv_append_paged_fp4",
                        "positions",
                        &[append_count as u64],
                        4,
                    )?,
                ),
            ],
        )?;
        let num_wg = 64u32;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, kcache_va);
            b.put_u64(8, vcache_va);
            b.put_u64(16, scale_k_va);
            b.put_u64(24, scale_v_va);
            b.put_u64(32, k_va);
            b.put_u64(40, v_va);
            b.put_u64(48, src_scale_k_va);
            b.put_u64(56, src_scale_v_va);
            b.put_u64(64, indices_va);
            b.put_u64(72, indptr_va);
            b.put_u64(80, last_page_len_va);
            b.put_u64(88, batch_indices_va);
            b.put_u64(96, positions_va);
            b.put_u32(104, append_count);
            b.put_u32(108, batch_size);
            b.put_u32(112, total_indices);
            b.put_u32(116, physical_blocks);
            b.put_u32(120, block_size);
            b.put_u32(124, num_wg * 256);
        })
    }

