            b.put_u64(16, scale_k_va);
            b.put_u64(24, scale_v_va);
            b.put_u64(32, k_va);
            b.put_u64(40, v_va);
            b.put_u64(48, indices_va);
            b.put_u64(56, indptr_va);
            b.put_u64(64, last_page_len_va);
            b.put_u64(72, batch_indices_va);
            b.put_u64(80, positions_va);
            b.put_u32(88, append_count);
            b.put_u32(92, batch_size);
            b.put_u32(96, total_indices);
            b.put_u32(100, physical_blocks);
            b.put_u32(104, block_size);
            b.put_u32(108, kv_heads);
