    pub fn arm_fp4_5d_kv_load_probe(
        &mut self,
        kcache_va: u64,
        vcache_va: u64,
        scale_k_va: u64,
        scale_v_va: u64,
        out_va: u64,
        physical_blocks: u32,
        block_size: u32,
        kv_heads: u32,
        phys_page: u32,
        kv_head: u32,
        group: u32,
        token_offset: u32,
        m_rows: u32,
    ) -> Result<()> {
        let kern = self.code.kernel("fp4_5d_kv_load_probe")?;
        if physical_blocks == 0 {
            return Err(anyhow!(
                "fp4_5d_kv_load_probe physical_blocks must be non-zero"
            ));
        }
        if block_size == 0 {
            return Err(anyhow!("fp4_5d_kv_load_probe block_size must be non-zero"));
        }
        if kv_heads == 0 {
            return Err(anyhow!("fp4_5d_kv_load_probe kv_heads must be non-zero"));
        }
        if phys_page >= physical_blocks {
            return Err(anyhow!(
                "fp4_5d_kv_load_probe phys_page {phys_page} exceeds physical_blocks {physical_blocks}"
            ));
        }
        if kv_head >= kv_heads {
            return Err(anyhow!(
                "fp4_5d_kv_load_probe kv_head {kv_head} exceeds kv_heads {kv_heads}"
            ));
        }
        if group >= 4 {
            return Err(anyhow!("fp4_5d_kv_load_probe group {group} must be < 4"));
        }
        if token_offset >= block_size {
            return Err(anyhow!(
                "fp4_5d_kv_load_probe token_offset {token_offset} exceeds block_size {block_size}"
            ));
        }
        if m_rows == 0 || m_rows > 8 {
            return Err(anyhow!(
                "fp4_5d_kv_load_probe m_rows {m_rows} must be in 1..=8"
            ));
        }
        self.validate_kernel_spans(
            "fp4_5d_kv_load_probe",
            &[
                (
                    "kcache",
                    kcache_va,
                    bytes_for(
                        "fp4_5d_kv_load_probe",
                        "kcache",
                        &[
                            physical_blocks as u64,
                            kv_heads as u64,
                            4,
                            block_size as u64,
                            16,
                        ],
                        1,
                    )?,
                ),
                (
                    "vcache",
                    vcache_va,
                    bytes_for(
                        "fp4_5d_kv_load_probe",
                        "vcache",
                        &[
                            physical_blocks as u64,
                            kv_heads as u64,
                            4,
                            block_size as u64,
                            16,
                        ],
                        1,
                    )?,
                ),
                (
                    "scale_k",
                    scale_k_va,
                    bytes_for(
                        "fp4_5d_kv_load_probe",
                        "scale_k",
                        &[
                            physical_blocks as u64,
                            kv_heads as u64,
                            4,
                            block_size as u64,
                        ],
                        1,
                    )?,
                ),
                (
                    "scale_v",
                    scale_v_va,
                    bytes_for(
                        "fp4_5d_kv_load_probe",
                        "scale_v",
                        &[
                            physical_blocks as u64,
                            kv_heads as u64,
                            4,
                            block_size as u64,
                        ],
                        1,
                    )?,
                ),
                (
                    "out",
                    out_va,
                    bytes_for("fp4_5d_kv_load_probe", "out", &[m_rows as u64, 40], 1)?,
                ),
            ],
        )?;
        let num_wg = 1u32;
        self.arm_grid(&kern, num_wg, 256, |b| {
            b.put_u64(0, kcache_va);
            b.put_u64(8, vcache_va);
            b.put_u64(16, scale_k_va);
            b.put_u64(24, scale_v_va);
            b.put_u64(32, out_va);
            b.put_u32(40, physical_blocks);
            b.put_u32(44, block_size);
            b.put_u32(48, kv_heads);
            b.put_u32(52, phys_page);
            b.put_u32(56, kv_head);
            b.put_u32(60, group);
            b.put_u32(64, token_offset);
            b.put_u32(68, m_rows);
            b.put_u32(72, num_wg * 256);
        })
    }

    /// Enqueue (without waiting) per-head RMSNorm (QK-norm): each of `nheads`
    /// D-slices normalized with shared weight w[D]. One workgroup per head.
    pub fn arm_rmsnorm_heads(
        &mut self,
        x_va: u64,
        w_va: u64,
        nheads: u32,
        d: u32,
        eps: f32,
    ) -> Result<()> {
        let kern = self.code.kernel("rmsnorm_heads")?;
        self.validate_kernel_spans(
            "rmsnorm_heads",
            &[
                (
                    "x",
                    x_va,
                    bytes_for("rmsnorm_heads", "x", &[nheads as u64, d as u64], 2)?,
                ),
                ("w", w_va, bytes_for("rmsnorm_heads", "w", &[d as u64], 2)?),
            ],
        )?;
        self.arm_grid(&kern, nheads, 256, |b| {
            b.put_u64(0, x_va);
            b.put_u64(8, w_va);
            b.put_u32(16, nheads);
            b.put_u32(20, d);
            b.put_f32(24, eps);
        })
    }

    /// Enqueue (without waiting) fused Q/K epilogue:
    /// f32 projection row -> f16 cast -> RMSNorm -> RoPE, per head.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_cast_rmsnorm_rope_heads(
        &mut self,
        src_va: u64,
        w_va: u64,
        dst_va: u64,
        nheads: u32,
        d: u32,
        pos: u32,
        theta: f32,
        eps: f32,
    ) -> Result<()> {
        let kern = self.code.kernel("cast_rmsnorm_rope_heads")?;
        self.validate_kernel_spans(
            "cast_rmsnorm_rope_heads",
            &[
                (
                    "src",
                    src_va,
                    bytes_for(
                        "cast_rmsnorm_rope_heads",
                        "src",
                        &[nheads as u64, d as u64],
                        4,
                    )?,
                ),
                (
                    "w",
                    w_va,
                    bytes_for("cast_rmsnorm_rope_heads", "w", &[d as u64], 2)?,
                ),
                (
                    "dst",
                    dst_va,
                    bytes_for(
                        "cast_rmsnorm_rope_heads",
                        "dst",
                        &[nheads as u64, d as u64],
                        2,
                    )?,
                ),
            ],
        )?;
        self.arm_grid(&kern, nheads, 256, |b| {
            b.put_u64(0, src_va);
            b.put_u64(8, w_va);
            b.put_u64(16, dst_va);
            b.put_u32(24, nheads);
            b.put_u32(28, d);
            b.put_u32(32, pos);
            b.put_f32(36, theta);
            b.put_f32(40, eps);
        })
    }

    /// Enqueue (without waiting) fused Q+K epilogue in one dispatch:
    /// f32 projection rows -> f16 cast -> RMSNorm -> RoPE, per Q/K head.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_cast_rmsnorm_rope_qk_heads(
        &mut self,
        q_src_va: u64,
        q_w_va: u64,
        q_dst_va: u64,
        k_src_va: u64,
        k_w_va: u64,
        k_dst_va: u64,
        q_heads: u32,
        k_heads: u32,
        d: u32,
        pos: u32,
        theta: f32,
        eps: f32,
    ) -> Result<()> {
        let kern = self.code.kernel("cast_rmsnorm_rope_qk_heads")?;
        if q_heads == 0 || k_heads == 0 {
            return Err(anyhow!(
                "cast_rmsnorm_rope_qk_heads requires non-zero q_heads and k_heads: q_heads={q_heads}, k_heads={k_heads}"
            ));
        }
        let total = q_heads.checked_add(k_heads).ok_or_else(|| {
            anyhow!("cast_rmsnorm_rope_qk_heads head count overflows: q_heads={q_heads}, k_heads={k_heads}")
        })?;
        self.validate_kernel_spans(
            "cast_rmsnorm_rope_qk_heads",
            &[
                (
                    "q_src",
                    q_src_va,
                    bytes_for(
                        "cast_rmsnorm_rope_qk_heads",
                        "q_src",
                        &[q_heads as u64, d as u64],
                        4,
                    )?,
                ),
                (
                    "q_w",
                    q_w_va,
                    bytes_for("cast_rmsnorm_rope_qk_heads", "q_w", &[d as u64], 2)?,
                ),
                (
                    "q_dst",
                    q_dst_va,
                    bytes_for(
                        "cast_rmsnorm_rope_qk_heads",
                        "q_dst",
                        &[q_heads as u64, d as u64],
                        2,
                    )?,
                ),
                (
                    "k_src",
                    k_src_va,
                    bytes_for(
                        "cast_rmsnorm_rope_qk_heads",
                        "k_src",
                        &[k_heads as u64, d as u64],
                        4,
                    )?,
                ),
                (
                    "k_w",
                    k_w_va,
                    bytes_for("cast_rmsnorm_rope_qk_heads", "k_w", &[d as u64], 2)?,
                ),
                (
                    "k_dst",
                    k_dst_va,
                    bytes_for(
                        "cast_rmsnorm_rope_qk_heads",
                        "k_dst",
                        &[k_heads as u64, d as u64],
                        2,
                    )?,
                ),
            ],
        )?;
        self.arm_grid(&kern, total, 256, |b| {
            b.put_u64(0, q_src_va);
            b.put_u64(8, q_w_va);
            b.put_u64(16, q_dst_va);
            b.put_u64(24, k_src_va);
            b.put_u64(32, k_w_va);
            b.put_u64(40, k_dst_va);
            b.put_u32(48, q_heads);
            b.put_u32(52, k_heads);
            b.put_u32(56, d);
            b.put_u32(60, pos);
            b.put_f32(64, theta);
            b.put_f32(68, eps);
        })
    }

    /// Purpose-built Qwen decode epilogue plus cache admission for one token:
    /// Q64/KV4/D128 QK-norm+RoPE, with K/V written directly to paged FP4 cache.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta(
        &mut self,
        q_src_va: u64,
        q_w_va: u64,
        q_dst_va: u64,
        k_src_va: u64,
        k_w_va: u64,
        v_va: u64,
        kcache_va: u64,
        vcache_va: u64,
        scale_k_va: u64,
        scale_v_va: u64,
        indices_va: u64,
        indptr_va: u64,
        last_page_len_va: u64,
        batch_indices_va: u64,
        positions_va: u64,
        total_indices: u32,
        physical_blocks: u32,
        block_size: u32,
        theta: f32,
        eps: f32,
    ) -> Result<()> {
        let kern = self
            .code
            .kernel("cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta")?;
        if total_indices == 0 {
            return Err(anyhow!("cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta total_indices must be non-zero"));
        }
        if physical_blocks == 0 {
            return Err(anyhow!("cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta physical_blocks must be non-zero"));
        }
        if block_size == 0 {
            return Err(anyhow!(
                "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta block_size must be non-zero"
            ));
        }
        physical_blocks.checked_mul(block_size).ok_or_else(|| {
            anyhow!(
                "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta physical row count overflows u32: physical_blocks={physical_blocks}, block_size={block_size}"
            )
        })?;
        self.validate_kernel_spans(
            "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
            &[
                (
                    "q_src",
                    q_src_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "q_src",
                        &[64, 128],
                        4,
                    )?,
                ),
                (
                    "q_w",
                    q_w_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "q_w",
                        &[128],
                        2,
                    )?,
                ),
                (
                    "q_dst",
                    q_dst_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "q_dst",
                        &[64, 128],
                        2,
                    )?,
                ),
                (
                    "k_src",
                    k_src_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "k_src",
                        &[4, 128],
                        4,
                    )?,
                ),
                (
                    "k_w",
                    k_w_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "k_w",
                        &[128],
                        2,
                    )?,
                ),
                (
                    "v",
                    v_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "v",
                        &[4, 128],
                        4,
                    )?,
                ),
                (
                    "kcache",
                    kcache_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "kcache",
                        &[4, physical_blocks as u64, block_size as u64, 64],
                        1,
                    )?,
                ),
                (
                    "vcache",
                    vcache_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "vcache",
                        &[4, physical_blocks as u64, block_size as u64, 64],
                        1,
                    )?,
                ),
                (
                    "scale_k",
                    scale_k_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "scale_k",
                        &[4, physical_blocks as u64, block_size as u64, 4],
                        1,
                    )?,
                ),
                (
                    "scale_v",
                    scale_v_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "scale_v",
                        &[4, physical_blocks as u64, block_size as u64, 4],
                        1,
                    )?,
                ),
                (
                    "indices",
                    indices_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "indices",
                        &[total_indices as u64],
                        4,
                    )?,
                ),
                (
                    "indptr",
                    indptr_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "indptr",
                        &[2],
                        4,
                    )?,
                ),
                (
                    "last_page_len",
                    last_page_len_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "last_page_len",
                        &[1],
                        4,
                    )?,
                ),
                (
                    "batch_indices",
                    batch_indices_va,
                    bytes_for(
                        "cast_qk_rope_append_paged_fp4_vf32_q64_k4_d128_meta",
                        "batch_indices",
                        &[1],
                        4,
                    )?,
                ),
                ("positions", positions_va, 4),
            ],
        )?;
        self.arm_grid(&kern, 68, 64, |b| {
            b.put_u64(0, q_src_va);
            b.put_u64(8, q_w_va);
            b.put_u64(16, q_dst_va);
            b.put_u64(24, k_src_va);
            b.put_u64(32, k_w_va);
            b.put_u64(40, v_va);
            b.put_u64(48, kcache_va);
            b.put_u64(56, vcache_va);
            b.put_u64(64, scale_k_va);
            b.put_u64(72, scale_v_va);
            b.put_u64(80, indices_va);
            b.put_u64(88, indptr_va);
            b.put_u64(96, last_page_len_va);
            b.put_u64(104, batch_indices_va);
            b.put_u64(112, positions_va);
            b.put_u32(120, total_indices);
            b.put_u32(124, physical_blocks);
            b.put_u32(128, block_size);
            b.put_f32(132, theta);
            b.put_f32(136, eps);
        })
    }

