    /// Enqueue (without waiting) descriptor-driven f32->f16 cast. The kernel
    /// receives only descriptor/status pointers as kernargs; input, output,
    /// element count, and grid-stride are loaded by the GPU from the descriptor.
    pub fn arm_cast_f32_f16_descriptor(
        &mut self,
        descriptor_va: u64,
        status_va: u64,
        in_va: u64,
        out_va: u64,
        n: u32,
    ) -> Result<()> {
        if n == 0 {
            return Err(anyhow!("cast_f32_f16_descriptor requires n > 0"));
        }
        if descriptor_va & 0xf != 0 || status_va & 0xf != 0 {
            return Err(anyhow!(
                "cast_f32_f16_descriptor requires 16-byte aligned descriptor/status buffers"
            ));
        }
        let kern = self.code.kernel("cast_f32_f16_descriptor")?;
        self.validate_kernel_spans(
            "cast_f32_f16_descriptor",
            &[
                (
                    "descriptor",
                    descriptor_va,
                    bytes_for("cast_f32_f16_descriptor", "descriptor", &[8], 8)?,
                ),
                (
                    "status",
                    status_va,
                    bytes_for("cast_f32_f16_descriptor", "status", &[9], 8)?,
                ),
                (
                    "in_from_descriptor",
                    in_va,
                    bytes_for(
                        "cast_f32_f16_descriptor",
                        "in_from_descriptor",
                        &[n as u64],
                        4,
                    )?,
                ),
                (
                    "out_from_descriptor",
                    out_va,
                    bytes_for(
                        "cast_f32_f16_descriptor",
                        "out_from_descriptor",
                        &[n as u64],
                        2,
                    )?,
                ),
            ],
        )?;
        self.arm_grid(&kern, 256, 256, |b| {
            b.put_u64(0, descriptor_va);
            b.put_u64(8, status_va);
        })
    }

    /// Enqueue (without waiting) an f32->bf16 elementwise cast over n elements.
