    /// Enqueue (without waiting) a read-only GPU probe for the packed resident
    /// layer-runner descriptor table. The kernel validates the table from HBM
    /// before later execution kernels are allowed to consume descriptor rows.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_resident_descriptor_table_probe(
        &mut self,
        descriptor_va: u64,
        out_va: u64,
        expected_magic: u64,
        expected_version: u64,
        rows: u32,
        u64s_per_row: u32,
        expected_checksum: u64,
    ) -> Result<()> {
        if rows == 0 {
            return Err(anyhow!(
                "resident descriptor table probe requires at least one row"
            ));
        }
        if u64s_per_row != 8 {
            return Err(anyhow!(
                "resident descriptor table probe requires 8 u64s per row (got {u64s_per_row})"
            ));
        }
        if descriptor_va & 0xf != 0 || out_va & 0xf != 0 {
            return Err(anyhow!(
                "resident descriptor table probe requires 16-byte aligned buffers"
            ));
        }
        if expected_version > u32::MAX as u64 {
            return Err(anyhow!(
                "resident descriptor table probe version does not fit u32"
            ));
        }
        let descriptor_words = (rows as u64)
            .checked_mul(u64s_per_row as u64)
            .ok_or_else(|| anyhow!("resident descriptor table probe word count overflows"))?;
        let kern = self.code.kernel("resident_descriptor_table_probe")?;
        self.validate_kernel_spans(
            "resident_descriptor_table_probe",
            &[
                (
                    "descriptors",
                    descriptor_va,
                    bytes_for(
                        "resident_descriptor_table_probe",
                        "descriptors",
                        &[descriptor_words],
                        8,
                    )?,
                ),
                (
                    "out",
                    out_va,
                    bytes_for("resident_descriptor_table_probe", "out", &[8], 8)?,
                ),
            ],
        )?;
        self.arm_grid(&kern, 1, 256, |b| {
            b.put_u64(0, descriptor_va);
            b.put_u64(8, out_va);
            b.put_u32(16, expected_magic as u32);
            b.put_u32(20, (expected_magic >> 32) as u32);
            b.put_u32(24, expected_version as u32);
            b.put_u32(28, rows);
            b.put_u32(32, u64s_per_row);
            b.put_u32(36, expected_checksum as u32);
            b.put_u32(40, (expected_checksum >> 32) as u32);
            b.put_u32(44, 256);
        })
    }

