    /// Enqueue (without waiting) a GPU-side O(1) resolver probe for the dense
    /// output slot table. The resolver consumes the all-layer descriptor table
    /// and a GPU-visible layer->row index table, proving the future device-side
    /// result applier can key a layer without a linear descriptor scan.
    #[allow(clippy::too_many_arguments)]
    pub fn arm_resident_dense_output_slot_resolver_probe(
        &mut self,
        descriptor_va: u64,
        layer_index_va: u64,
        out_va: u64,
        expected_magic: u64,
        expected_version: u64,
        rows: u32,
        u64s_per_row: u32,
        layer_index_entries: u32,
        target_layer: u32,
        expected_role_mask: u32,
        expected_slot_count: u32,
        expected_flags: u64,
        expected_row_index: u32,
        expected_row_checksum: u64,
    ) -> Result<()> {
        if rows == 0 {
            return Err(anyhow!(
                "resident dense output slot resolver probe requires at least one row"
            ));
        }
        if u64s_per_row != 8 {
            return Err(anyhow!(
                "resident dense output slot resolver probe requires 8 u64s per row (got {u64s_per_row})"
            ));
        }
        if layer_index_entries == 0 || target_layer >= layer_index_entries {
            return Err(anyhow!(
                "resident dense output slot resolver probe target layer {target_layer} is outside index entries {layer_index_entries}"
            ));
        }
        if descriptor_va & 0xf != 0 || layer_index_va & 0xf != 0 || out_va & 0xf != 0 {
            return Err(anyhow!(
                "resident dense output slot resolver probe requires 16-byte aligned buffers"
            ));
        }
        if expected_version > u32::MAX as u64 {
            return Err(anyhow!(
                "resident dense output slot resolver probe version does not fit u32"
            ));
        }
        let descriptor_words = (rows as u64)
            .checked_mul(u64s_per_row as u64)
            .ok_or_else(|| {
                anyhow!("resident dense output slot resolver descriptor word count overflows")
            })?;
        let kern = self
            .code
            .kernel("resident_dense_output_slot_resolver_probe")?;
        self.validate_kernel_spans(
            "resident_dense_output_slot_resolver_probe",
            &[
                (
                    "descriptors",
                    descriptor_va,
                    bytes_for(
                        "resident_dense_output_slot_resolver_probe",
                        "descriptors",
                        &[descriptor_words],
                        8,
                    )?,
                ),
                (
                    "layer_row_index",
                    layer_index_va,
                    bytes_for(
                        "resident_dense_output_slot_resolver_probe",
                        "layer_row_index",
                        &[layer_index_entries as u64],
                        4,
                    )?,
                ),
                (
                    "out",
                    out_va,
                    bytes_for("resident_dense_output_slot_resolver_probe", "out", &[16], 8)?,
                ),
            ],
        )?;
        self.arm_grid(&kern, 1, 256, |b| {
            b.put_u64(0, descriptor_va);
            b.put_u64(8, layer_index_va);
            b.put_u64(16, out_va);
            b.put_u32(24, expected_magic as u32);
            b.put_u32(28, (expected_magic >> 32) as u32);
            b.put_u32(32, expected_version as u32);
            b.put_u32(36, rows);
            b.put_u32(40, u64s_per_row);
            b.put_u32(44, layer_index_entries);
            b.put_u32(48, target_layer);
            b.put_u32(52, expected_role_mask);
            b.put_u32(56, expected_slot_count);
            b.put_u32(60, expected_flags as u32);
            b.put_u32(64, (expected_flags >> 32) as u32);
            b.put_u32(68, expected_row_index);
            b.put_u32(72, expected_row_checksum as u32);
            b.put_u32(76, (expected_row_checksum >> 32) as u32);
            b.put_u32(80, 256);
        })
    }

    /// Enqueue (without waiting) a GPU-side readiness frontier probe for the
    /// resident DAG edge table. The probe consumes only pointer-free HBM rows
    /// plus runtime satisfaction/completion masks; it does not dispatch work.
