            b.put_u32(36, expected_candidate_wait_mask as u32);
            b.put_u32(40, (expected_candidate_wait_mask >> 32) as u32);
            b.put_u32(44, expected_candidate_signal_mask as u32);
            b.put_u32(48, (expected_candidate_signal_mask >> 32) as u32);
